<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateVariable\Domain;

use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableUidVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableCodeVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor\TemplateVariableCodeAccessor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTenantVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor\TemplateVariableTenantAccessor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableTypeVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor\TemplateVariableTypeAccessor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableValueVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor\TemplateVariableValueAccessor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableEnabledVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor\TemplateVariableEnabledAccessor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\TemplateVariableVersionVO;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\ValueObject\Accessor\TemplateVariableVersionAccessor;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Formula\EnabledCalculator;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Event\TemplateVariableCreateEvent;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Event\TemplateVariableUpdateEvent;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Event\TemplateVariableDeleteEvent;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Event\TemplateVariableEnableEvent;
use Civi\Lughauth\Features\Document\TemplateVariable\Domain\Event\TemplateVariableDisableEvent;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

class TemplateVariable extends TemplateVariableRef
{
    use TemplateVariableCodeAccessor;
    use TemplateVariableTenantAccessor;
    use TemplateVariableTypeAccessor;
    use TemplateVariableValueAccessor;
    use TemplateVariableEnabledAccessor;
    use TemplateVariableVersionAccessor;
    private array $recordedEvents = [];

    public function __construct(
        TemplateVariableUidVO|string $uid,
        TemplateVariableCodeVO|string $code,
        TemplateVariableTenantVO|TenantRef $tenant,
        TemplateVariableTypeVO|string $type,
        TemplateVariableValueVO|string|null $value = null,
        TemplateVariableEnabledVO|bool|null $enabled = null,
        TemplateVariableVersionVO|int|null $version = null,
    ) {
        parent::__construct($uid);
        $this->_code = TemplateVariableCodeVO::from($code);
        $this->_tenant = TemplateVariableTenantVO::from($tenant);
        $this->_type = TemplateVariableTypeVO::from($type);
        $this->_value = null === $value ? TemplateVariableValueVO::empty() : TemplateVariableValueVO::from($value);
        $this->_enabled = null === $enabled ? TemplateVariableEnabledVO::empty() : TemplateVariableEnabledVO::from($enabled);
        $this->_version = null === $version ? TemplateVariableVersionVO::empty() : TemplateVariableVersionVO::from($version);
    }
    public function replace(TemplateVariableAttributes $values): TemplateVariable
    {
        $value = clone $this;
        $value->_code = $values->getCodeOrDefault($this->_code);
        $value->_tenant = $values->getTenantOrDefault($this->_tenant);
        $value->_type = $values->getTypeOrDefault($this->_type);
        $value->_value = $values->getValueOrDefault($this->_value);
        $value->_enabled = $values->getEnabledOrDefault($this->_enabled);
        $value->_version = $values->getVersionOrDefault($this->_version);
        return $value;
    }
    public static function calculatedFields(): array
    {
        return [ 'enabled'];
    }
    public static function create(TemplateVariableAttributes $values): TemplateVariable
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled());
        $value = $calculated->build();
        $value->recordedEvents[] = new TemplateVariableCreateEvent($value);
        return $value;
    }
    public function update(TemplateVariableAttributes $values): TemplateVariable
    {
        $calculated = clone $values;
        $calculated->enabled(EnabledCalculator::calculateEnabled($this));
        $value = $this->replace($calculated);
        $value->recordedEvents[] = new TemplateVariableUpdateEvent($value, $this);
        return $value;
    }
    public function delete(): TemplateVariable
    {
        $value = clone $this;
        $value->recordedEvents[] = new TemplateVariableDeleteEvent($value);
        return $value;
    }
    public function enable(): TemplateVariable
    {
        $value = clone $this;
        $value->_enabled = TemplateVariableEnabledVO::from(true);
        $value->recordedEvents[] = new TemplateVariableEnableEvent($value, original: $this);
        return $value;
    }
    public function disable(): TemplateVariable
    {
        $value = clone $this;
        $value->_enabled = TemplateVariableEnabledVO::from(false);
        $value->recordedEvents[] = new TemplateVariableDisableEvent($value, original: $this);
        return $value;
    }
    public function asPublicJson(): array
    {
        $data = [];
        $data['uid'] = $this->uid();
        $data['code'] = $this->getCode();
        $data['tenant'] = [ '$ref' => $this->getTenant()->uid() ];
        $data['type'] = $this->getType();
        $data['value'] = $this->getValue();
        $data['enabled'] = $this->isEnabled();
        $data['version'] = $this->getVersion();
        return $data;
    }
    public function toAttributes(): TemplateVariableAttributes
    {
        return (new TemplateVariableAttributes())
          ->uid($this->uid())
          ->code($this->_code)
          ->tenant($this->_tenant)
          ->type($this->_type)
          ->value($this->_value)
          ->enabled($this->_enabled)
          ->version($this->_version);
    }
    public function getTheEvents(): array
    {
        return [...$this->recordedEvents];
    }
}
